using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Rask.Storage;

/// <summary>The EF Core mapping for <see cref="StoredFileBytes"/>: varbinary(max) on SQL Server, bytea, a SQLite blob.</summary>
internal sealed class StoredFileBytesConfiguration : IEntityTypeConfiguration<StoredFileBytes>
{
    public void Configure(EntityTypeBuilder<StoredFileBytes> entity)
    {
        entity.HasKey(b => b.Id);

        // The file's id, set before the row is written: never generated by the store.
        entity.Property(b => b.Id).ValueGeneratedNever();
        entity.Property(b => b.Bytes).IsRequired();

        // No relationship to StoredFile, deliberately: an adopted schema creates both tables by hand, and the sweep
        // removes bytes whose row is gone, as it does in a bucket.
    }
}
